#!/usr/bin/env python3
"""Regenerates Sources/AIUsage/ProviderIcons.swift from Assets/ProviderMarks/*.svg.

Each SVG is converted to a vector PDF (needs `rsvg-convert`: `brew install librsvg`) and embedded
as base64. NSImage draws PDF data as vectors, so marks stay sharp at every size and scale, and
the app needs no SwiftPM resource bundle. `<name>-dark.svg` is the variant for dark appearance."""
import base64, pathlib, subprocess

root = pathlib.Path(__file__).resolve().parent.parent
marks = sorted((root / "Assets/ProviderMarks").glob("*.svg"))
lines = [
    "// Generated by Scripts/embed_marks.py from Assets/ProviderMarks (see NOTICE.md there). Do not edit.",
    "import Foundation",
    "",
    "enum ProviderIconData {",
    "    /// Vector PDFs, base64.",
    "    static let pdf: [String: String] = [",
]
for p in marks:
    pdf = subprocess.run(["rsvg-convert", "-f", "pdf", str(p)], check=True, capture_output=True).stdout
    lines.append(f'        "{p.stem}": "{base64.b64encode(pdf).decode()}",')
lines += ["    ]", "}", ""]
(root / "Sources/AIUsage/ProviderIcons.swift").write_text("\n".join(lines))
print(f"embedded {len(marks)} marks")
